        if("Response".equals(type)){var assertion=element(d,root,A,"saml:Assertion",null);assertion.setAttribute("ID",id+"-assertion");assertion.setAttribute("Version","2.0");assertion.setAttribute("IssueInstant",Instant.now().toString());element(d,assertion,A,"saml:Issuer",issuer);var subject=element(d,assertion,A,"saml:Subject",null);element(d,subject,A,"saml:NameID",name);var confirmation=element(d,subject,A,"saml:SubjectConfirmation",null);confirmation.setAttribute("Method","urn:oasis:names:tc:SAML:2.0:cm:bearer");var data=element(d,confirmation,A,"saml:SubjectConfirmationData",null);data.setAttribute("Recipient",destination);data.setAttribute("InResponseTo",responseTo);data.setAttribute("NotOnOrAfter",Instant.now().plusSeconds(300).toString());var conditions=element(d,assertion,A,"saml:Conditions",null);var restriction=element(d,conditions,A,"saml:AudienceRestriction",null);element(d,restriction,A,"saml:Audience",name.substring(name.indexOf('|')+1));var statement=element(d,assertion,A,"saml:AuthnStatement",null);statement.setAttribute("SessionIndex",session);statement.setAttribute("AuthnInstant",Instant.now().toString());subject.getFirstChild().setTextContent(name.substring(0,name.indexOf('|')));new XmlSigner().sign(assertion,target,(Element)assertion.getFirstChild().getNextSibling());}
