    static byte[] bytes(Element element){var doc=SecureXml.newDocument();doc.appendChild(doc.importNode(element,true));return SecureXml.serialize(doc);}
    static byte[] soap(Element inner){var d=SecureXml.newDocument();var root=d.createElementNS(SOAP,"soap:Envelope");d.appendChild(root);root.setAttributeNS("http://www.w3.org/2000/xmlns/","xmlns:soap",SOAP);var body=element(d,root,SOAP,"soap:Body",null);body.appendChild(d.importNode(inner,true));return SecureXml.serialize(d);}
