    public static void main(String[]args)throws Exception {require(args.length==3);var actor=new SoapContinuationActor(Path.of(args[0]),args[1],Path.of(args[2]));try{actor.run();actor.entries.clear();actor.decoded.clear();actor.trials.clear();actor.next=0;actor.continuation=new StopAfterErrorActor();actor.setOutput("mutant");actor.run();}finally{actor.server.stop(0);actor.executor.shutdownNow();}}
